content.content:
1	/*
2	  Терминал корабля: фосфорный экран, сканлайны, лёгкое дрожание яркости.
3	  Всё рисуется CSS — ни одной картинки, ни одного внешнего шрифта.
4	*/
5	
6	:root {
7	  --phosphor: #7dff9b;
8	  --phosphor-dim: #3d8a52;
9	  --phosphor-faint: #1c3d27;
10	  --amber: #ffb347;
11	  --amber-dim: #8a5f26;
12	  --alert: #ff4d4d;
13	  --bg: #050a06;
14	  --panel: #0a140c;
15	  --panel-edge: #16301c;
16	  --light-square: #17301d;
17	  --dark-square: #0d1e11;
18	
19	  --font: 'Consolas', 'DejaVu Sans Mono', 'Courier New', monospace;
20	  --board-max: min(72vh, 560px);
21	}
22	
23	* {
24	  box-sizing: border-box;
25	}
26	
27	html,
28	body {
29	  margin: 0;
30	  height: 100%;
31	  background: var(--bg);
32	  color: var(--phosphor);
33	  font-family: var(--font);
34	  font-size: 14px;
35	  letter-spacing: 0.04em;
36	  overflow: hidden;
37	}
38	
39	/* Сканлайны и виньетка — поверх всего, но не перехватывают клики. */
40	body::after {
41	  content: '';
42	  position: fixed;
43	  inset: 0;
44	  pointer-events: none;
45	  z-index: 100;
46	  background:
47	    repeating-linear-gradient(
48	      to bottom,
49	      rgba(0, 0, 0, 0.22) 0px,
50	      rgba(0, 0, 0, 0.22) 1px,
51	      transparent 1px,
52	      transparent 3px
53	    ),
54	    radial-gradient(ellipse at center, transparent 55%, rgba(0, 0, 0, 0.55) 100%);
55	  animation: flicker 5.5s infinite steps(60);
56	}
57	
58	@keyframes flicker {
59	  0%, 96%, 100% { opacity: 1; }
60	  97% { opacity: 0.93; }
61	  98% { opacity: 1; }
62	  99% { opacity: 0.96; }
63	}
64	
65	@media (prefers-reduced-motion: reduce) {
66	  body::after { animation: none; }
67	}
68	
69	.app {
70	  display: grid;
71	  grid-template-columns: 42px var(--board-max) minmax(300px, 1fr);
72	  grid-template-rows: auto 1fr auto;
73	  grid-template-areas:
74	    'head head head'
75	    'evalbar board side'
76	    'foot foot foot';
77	  gap: 12px;
78	  height: 100%;
79	  padding: 10px 14px;
80	  max-width: 1240px;
81	  margin: 0 auto;
82	}
83	
84	/* ─────────────────────────────────── шапка */
85	
86	.head {
87	  grid-area: head;
88	  display: flex;
89	  align-items: baseline;
90	  gap: 18px;
91	  flex-wrap: wrap;
92	  min-width: 0;
93	  border-bottom: 1px solid var(--panel-edge);
94	  padding-bottom: 6px;
95	}
96	
97	.title {
98	  flex: none;
99	  white-space: nowrap;
100	  font-weight: bold;
101	  font-size: 17px;
102	  letter-spacing: 0.22em;
103	  text-shadow: 0 0 8px rgba(125, 255, 155, 0.5);
104	}
105	
106	.head .status { color: var(--phosphor-dim); white-space: nowrap; }
107	.head .spacer { flex: 1; }
108	
109	.link-dot {
110	  display: inline-block;
111	  width: 8px;
112	  height: 8px;
113	  border-radius: 50%;
114	  background: var(--phosphor);
115	  margin-right: 6px;
116	  box-shadow: 0 0 6px var(--phosphor);
117	}
118	.link-dot.off { background: var(--alert); box-shadow: 0 0 6px var(--alert); }
119	
120	/* ─────────────────────────────────── шкала оценки */
121	
122	.evalbar {
123	  grid-area: evalbar;
124	  position: relative;
125	  border: 1px solid var(--panel-edge);
126	  /* Фон — доля КСЕНО, заливка — доля МОРПЕХОВ. Раньше шкала была «зелёное против
127	     пустого», то есть говорила на языке белых и чёрных, а не сторон этой игры. */
128	  background: linear-gradient(to bottom, var(--amber) 0%, var(--amber-dim) 100%);
129	  display: flex;
130	  flex-direction: column;
131	  justify-content: flex-end;
132	  overflow: hidden;
133	}
134	.evalbar .fill {
135	  background: linear-gradient(to top, var(--phosphor), var(--phosphor-dim));
136	  transition: height 260ms ease-out;
137	  height: 50%;
138	}
139	.evalbar .label {
140	  position: absolute;
141	  inset-inline: 0;
142	  top: 4px;
143	  text-align: center;
144	  font-size: 11px;
145	  color: #dfffe8;
146	  /* Подложка нужна: метка теперь ложится и на зелёное, и на янтарное. */
147	  background: rgba(5, 10, 6, 0.78);
148	  padding: 1px 0;
149	}
150	.evalbar.shallow .fill { opacity: 0.55; }
151	.evalbar.hidden { background: var(--dark-square); }
152	.evalbar.hidden .fill { height: 50% !important; opacity: 0.15; }
153	
154	/* ─────────────────────────────────── доска */
155	
156	.board-wrap { grid-area: board; display: flex; align-items: start; justify-content: center; }
157	
158	.board {
159	  position: relative;
160	  /* Баннер десанта уезжает за верхний край — без обрезки он висел бы поверх шапки. */
161	  overflow: hidden;
162	  width: var(--board-max);
163	  height: var(--board-max);
164	  border: 2px solid var(--panel-edge);
165	  background: var(--dark-square);
166	  user-select: none;
167	  touch-action: none;
168	}
169	
170	.squares {
171	  position: absolute;
172	  inset: 0;
173	  display: grid;
174	  grid-template-columns: repeat(8, 1fr);
175	  grid-template-rows: repeat(8, 1fr);
176	}
177	.sq { position: relative; }
178	.sq.light { background: var(--light-square); }
179	.sq.dark { background: var(--dark-square); }
180	.sq .coord {
181	  position: absolute;
182	  bottom: 1px;
183	  right: 3px;
184	  font-size: 9px;
185	  color: var(--phosphor-faint);
186	}
187	
188	.sq.sel { box-shadow: inset 0 0 0 2px var(--phosphor); }
189	.sq.target::before {
190	  content: '';
191	  position: absolute;
192	  inset: 38%;
193	  border-radius: 50%;
194	  background: var(--phosphor);
195	  opacity: 0.5;
196	}
197	.sq.target.capture::before {
198	  inset: 6%;
199	  border-radius: 0;
200	  background: transparent;
201	  box-shadow: inset 0 0 0 3px var(--amber);
202	  opacity: 0.75;
203	}
204	.sq.last { box-shadow: inset 0 0 0 2px var(--phosphor-dim); }
205	.sq.check { background: #3a0f0f; }
206	.sq.reinforced { box-shadow: inset 0 0 0 2px var(--amber); }
207	
208	.pieces { position: absolute; inset: 0; pointer-events: none; }
209	.piece {
210	  position: absolute;
211	  width: 12.5%;
212	  height: 12.5%;
213	  transition: transform 180ms ease-out;
214	  will-change: transform;
215	}
216	/* Отступ внутри клетки: без него фигуры упираются в края и доска читается как каша. */
217	.piece svg { width: 100%; height: 100%; display: block; padding: 7%; image-rendering: pixelated; }
218	.piece.dragging { transition: none; z-index: 5; filter: drop-shadow(0 0 6px rgba(125, 255, 155, 0.6)); }
219	
220	.piece .badge {
221	  position: absolute;
222	  left: 2px;
223	  top: 1px;
224	  font-size: 9px;
225	  line-height: 1;
226	  color: var(--phosphor-dim);
227	  text-shadow: 0 0 3px #000;
228	}
229	.piece[data-color='b'] .badge { color: var(--amber-dim); }
230	
231	/* Посадка десанта: фигура падает сверху с перелётом — это читается как посадка,
232	   а не как проявление. */
233	@keyframes land {
234	  0% { transform: translate(var(--tx), calc(var(--ty) - 44px)) scale(1.7); opacity: 0; }
235	  60% { opacity: 1; }
236	  100% { transform: translate(var(--tx), var(--ty)) scale(1); opacity: 1; }
237	}
238	.piece.landing { animation: land 340ms cubic-bezier(0.34, 1.56, 0.64, 1) backwards; }
239	
240	@keyframes shock {
241	  from { transform: scale(0.2); opacity: 0.7; }
242	  to { transform: scale(2.2); opacity: 0; }
243	}
244	.sq .shock {
245	  position: absolute;
246	  inset: 0;
247	  border: 2px solid var(--amber);
248	  border-radius: 50%;
249	  animation: shock 460ms ease-out forwards;
250	  pointer-events: none;
251	}
252	
253	@media (prefers-reduced-motion: reduce) {
254	  .piece { transition: none; }
255	  .piece.landing { animation: none; }
256	  .sq .shock { display: none; }
257	}
258	
259	/* ─────────────────────────────────── баннер десанта */
260	
261	.drop-banner {
262	  position: absolute;
263	  inset-inline: 0;
264	  top: 0;
265	  background: rgba(5, 10, 6, 0.92);
266	  border-bottom: 1px solid var(--amber);
267	  padding: 10px 14px;
268	  z-index: 10;
269	  transform: translateY(-100%);
270	  transition: transform 220ms ease-out;
271	}
272	.drop-banner.on { transform: translateY(0); }
273	.drop-banner .head-line {
274	  color: var(--amber);
275	  letter-spacing: 0.2em;
276	  font-weight: bold;
277	}
278	.drop-banner .phase { color: var(--phosphor-dim); font-size: 12px; margin-top: 4px; }
279	.drop-banner .bar { height: 4px; background: var(--panel-edge); margin-top: 6px; }
280	.drop-banner .bar > i { display: block; height: 100%; background: var(--amber); width: 0; transition: width 180ms linear; }
281	.board.busy .squares { opacity: 0.55; }
282	.board.busy { cursor: wait; }
283	
284	/* ─────────────────────────────────── правая колонка */
285	
286	.side {
287	  grid-area: side;
288	  display: flex;
289	  flex-direction: column;
290	  gap: 10px;
291	  min-height: 0;
292	}
293	
294	.panel {
295	  border: 1px solid var(--panel-edge);
296	  background: var(--panel);
297	  display: flex;
298	  flex-direction: column;
299	  min-height: 0;
300	}
301	.panel > h2 {
302	  margin: 0;
303	  padding: 5px 9px;
304	  font-size: 11px;
305	  letter-spacing: 0.2em;
306	  color: var(--phosphor-dim);
307	  border-bottom: 1px solid var(--panel-edge);
308	  font-weight: normal;
309	}
310	.panel > .body { padding: 7px 9px; overflow-y: auto; font-size: 12.5px; line-height: 1.55; }
311	.panel.grow { flex: 1; }
312	
313	.moves { font-variant-numeric: tabular-nums; }
314	.moves .row { display: grid; grid-template-columns: 30px 1fr 1fr; gap: 4px; }
315	.moves .n { color: var(--phosphor-faint); }
316	.moves .sep {
317	  grid-column: 1 / -1;
318	  color: var(--amber-dim);
319	  border-top: 1px dashed var(--amber-dim);
320	  margin: 3px 0;
321	  font-size: 10px;
322	  letter-spacing: 0.15em;
323	}
324	
325	.drop-entry { border-bottom: 1px dotted var(--panel-edge); padding-bottom: 5px; margin-bottom: 5px; }
326	.drop-entry:last-child { border-bottom: none; }
327	.drop-entry .when { color: var(--phosphor-faint); font-size: 11px; }
328	.drop-entry .marines { color: var(--phosphor); }
329	.drop-entry .xeno { color: var(--amber); }
330	.drop-entry .delta { color: var(--phosphor-dim); font-size: 11.5px; }
331	.drop-entry .warn { color: var(--amber); font-size: 11.5px; }
332	.drop-entry .chip {
333	  display: inline-block;
334	  border: 1px solid var(--phosphor-dim);
335	  padding: 0 5px;
336	  font-size: 10px;
337	  letter-spacing: 0.1em;
338	}
339	
340	/* ─────────────────────────────────── подвал */
341	
342	.foot {
343	  grid-area: foot;
344	  display: flex;
345	  align-items: center;
346	  gap: 14px;
347	  border-top: 1px solid var(--panel-edge);
348	  padding-top: 8px;
349	  flex-wrap: wrap;
350	}
351	.foot .spacer { flex: 1; }
352	
353	button {
354	  font-family: var(--font);
355	  font-size: 12px;
356	  letter-spacing: 0.12em;
357	  color: var(--phosphor);
358	  background: transparent;
359	  border: 1px solid var(--phosphor-dim);
360	  padding: 6px 11px;
361	  cursor: pointer;
362	  transition: background 120ms, box-shadow 120ms;
363	}
364	button:hover:not(:disabled) { background: rgba(125, 255, 155, 0.1); box-shadow: 0 0 8px rgba(125, 255, 155, 0.25); }
365	button:disabled { color: var(--phosphor-faint); border-color: var(--phosphor-faint); cursor: not-allowed; }
366	button.amber { color: var(--amber); border-color: var(--amber-dim); }
367	button.amber:hover:not(:disabled) { background: rgba(255, 179, 71, 0.12); box-shadow: 0 0 8px rgba(255, 179, 71, 0.25); }
368	
369	.pips { letter-spacing: 0.18em; }
370	
371	/* ─────────────────────────────────── кубики */
372	
373	.dice-box {
374	  display: flex;
375	  align-items: center;
376	  gap: 8px;
377	}
378	.die {
379	  width: 26px;
380	  height: 26px;
381	  border: 1px solid var(--phosphor-dim);
382	  display: grid;
383	  grid-template: repeat(3, 1fr) / repeat(3, 1fr);
384	  padding: 3px;
385	}
386	.die i { border-radius: 50%; background: var(--phosphor); width: 5px; height: 5px; align-self: center; justify-self: center; }
387	.die.rolling { animation: shake 90ms infinite; }
388	@keyframes shake {
389	  0% { transform: translate(0, 0) rotate(0deg); }
390	  33% { transform: translate(-1px, 1px) rotate(-4deg); }
391	  66% { transform: translate(1px, -1px) rotate(4deg); }
392	  100% { transform: translate(0, 0) rotate(0deg); }
393	}
394	.dice-text { color: var(--amber); font-size: 11.5px; }
395	
396	/* ─────────────────────────────────── оверлеи */
397	
398	.overlay {
399	  position: fixed;
400	  inset: 0;
401	  background: rgba(5, 10, 6, 0.9);
402	  display: none;
403	  align-items: center;
404	  justify-content: center;
405	  z-index: 50;
406	}
407	.overlay.on { display: flex; }
408	.overlay .card {
409	  border: 1px solid var(--phosphor-dim);
410	  background: var(--panel);
411	  padding: 26px 34px;
412	  text-align: center;
413	  min-width: 320px;
414	}
415	.overlay .card h3 { margin: 0 0 8px; letter-spacing: 0.2em; font-size: 22px; }
416	.overlay .card p { color: var(--phosphor-dim); margin: 4px 0 16px; }
417	
418	.drawer {
419	  position: fixed;
420	  top: 0;
421	  right: 0;
422	  bottom: 0;
423	  width: 330px;
424	  background: var(--panel);
425	  border-left: 1px solid var(--panel-edge);
426	  transform: translateX(100%);
427	  transition: transform 200ms ease-out;
428	  z-index: 60;
429	  padding: 16px;
430	  overflow-y: auto;
431	}
432	.drawer.on { transform: translateX(0); }
433	.drawer h3 { margin: 0 0 14px; letter-spacing: 0.2em; font-size: 13px; color: var(--phosphor-dim); }
434	.drawer label { display: block; margin: 12px 0 4px; font-size: 11.5px; color: var(--phosphor-dim); }
435	.drawer select,
436	.drawer input[type='number'] {
437	  width: 100%;
438	  background: var(--bg);
439	  color: var(--phosphor);
440	  border: 1px solid var(--panel-edge);
441	  font-family: var(--font);
442	  font-size: 12.5px;
443	  padding: 5px 7px;
444	}
445	.drawer .row-check { display: flex; align-items: center; gap: 8px; margin: 9px 0; font-size: 12px; }
446	.drawer .hint { color: var(--phosphor-faint); font-size: 11px; line-height: 1.5; margin-top: 3px; }
447	.drawer .teller-blurb { color: var(--amber); font-size: 11.5px; line-height: 1.5; margin-top: 6px; min-height: 34px; }
448	
449	.toast {
450	  position: fixed;
451	  left: 50%;
452	  bottom: 24px;
453	  transform: translateX(-50%) translateY(20px);
454	  background: var(--panel);
455	  border: 1px solid var(--amber-dim);
456	  color: var(--amber);
457	  padding: 8px 16px;
458	  font-size: 12px;
459	  opacity: 0;
460	  transition: opacity 200ms, transform 200ms;
461	  pointer-events: none;
462	  z-index: 70;
463	}
464	.toast.on { opacity: 1; transform: translateX(-50%) translateY(0); }
465	
466	/* ─────────────────────────────────── узкий экран */
467	
468	@media (max-width: 980px) {
469	  html, body { overflow: auto; }
470	  .app {
471	    height: auto;
472	    min-height: 100%;
473	    grid-template-columns: 1fr;
474	    grid-template-rows: auto auto auto auto auto;
475	    grid-template-areas: 'head' 'evalbar' 'board' 'foot' 'side';
476	    --board-max: min(92vw, 520px);
477	  }
478	  .side { min-height: 320px; }
479	  .panel > .body { max-height: 200px; }
480	  /* В горизонтальном виде доля морпехов идёт слева направо, а фон-янтарь остаётся
481	     справа: направление совпадает с привычным чтением. */
482	  .evalbar {
483	    height: 22px;
484	    flex-direction: row;
485	    justify-content: flex-start;
486	    background: linear-gradient(to right, var(--amber-dim) 0%, var(--amber) 100%);
487	  }
488	  .evalbar .fill {
489	    height: 100% !important;
490	    width: 50%;
491	    transition: width 260ms ease-out;
492	    background: linear-gradient(to right, var(--phosphor-dim), var(--phosphor));
493	  }
494	  /* В узком окне подвал раскладывается в несколько строк, но КНОПКИ не рвутся
495	     по словам: «БРОСОК · МОРПЕХИ» в три строки выглядит поломкой, а не вёрсткой. */
496	  .foot {
497	    flex-wrap: wrap;
498	    overflow: visible;
499	    justify-content: center;
500	    row-gap: 8px;
501	  }
502	  .foot button { white-space: nowrap; }
503	  .foot .spacer { display: none; }
504	  .dice-text { max-width: 100%; white-space: normal; }
505	  .board-wrap { justify-content: center; }
506	}
507	
508	/* ─────────────────────────────────── стартовый экран */
509	
510	.start {
511	  position: fixed;
512	  inset: 0;
513	  z-index: 90;
514	  background: var(--bg);
515	  display: flex;
516	  align-items: center;
517	  justify-content: center;
518	  overflow-y: auto;
519	  padding: 20px;
520	}
521	.start.off { display: none; }
522	
523	.start-card {
524	  width: min(620px, 100%);
525	  border: 1px solid var(--phosphor-dim);
526	  background: var(--panel);
527	  padding: 22px 28px 26px;
528	  box-shadow: 0 0 40px rgba(125, 255, 155, 0.08);
529	}
530	
531	.boot {
532	  color: var(--phosphor-faint);
533	  font-size: 11px;
534	  line-height: 1.7;
535	  min-height: 54px;
536	  white-space: pre-wrap;
537	  margin-bottom: 12px;
538	}
539	
540	.start-title {
541	  font-size: 25px;
542	  letter-spacing: 0.3em;
543	  text-align: center;
544	  text-shadow: 0 0 14px rgba(125, 255, 155, 0.45);
545	}
546	.start-sub {
547	  text-align: center;
548	  color: var(--phosphor-dim);
549	  font-size: 11px;
550	  letter-spacing: 0.16em;
551	  margin: 6px 0 22px;
552	  padding-bottom: 14px;
553	  border-bottom: 1px solid var(--panel-edge);
554	}
555	
556	.opt {
557	  display: flex;
558	  align-items: center;
559	  gap: 14px;
560	  margin: 11px 0 3px;
561	}
562	.opt-label {
563	  flex: 1;
564	  color: var(--phosphor-dim);
565	  font-size: 11.5px;
566	  letter-spacing: 0.1em;
567	}
568	.opt-note {
569	  color: var(--amber-dim);
570	  font-size: 11px;
571	  line-height: 1.45;
572	  margin: 0 0 8px;
573	  min-height: 15px;
574	}
575	.opt.disabled { opacity: 0.35; pointer-events: none; }
576	
577	.seg { display: flex; }
578	.seg button {
579	  border-right-width: 0;
580	  padding: 5px 10px;
581	  font-size: 11.5px;
582	  letter-spacing: 0.08em;
583	}
584	.seg button:last-child { border-right-width: 1px; }
585	.seg button.on {
586	  background: rgba(125, 255, 155, 0.16);
587	  color: var(--phosphor);
588	  border-color: var(--phosphor);
589	  box-shadow: inset 0 0 10px rgba(125, 255, 155, 0.18);
590	}
591	
592	.start-go { text-align: center; margin-top: 20px; }
593	.start-go button {
594	  font-size: 15px;
595	  letter-spacing: 0.24em;
596	  padding: 11px 30px;
597	  color: var(--amber);
598	  border-color: var(--amber);
599	}
600	.start-go button:hover { background: rgba(255, 179, 71, 0.14); box-shadow: 0 0 16px rgba(255, 179, 71, 0.3); }
601	
