1	// Доска: 64 статических поля и отдельный слой фигур.
2	//
3	// Ключевое решение — поля НИКОГДА не пересоздаются, а фигуры живут в своём слое и
4	// позиционируются трансформацией. Диффинг по устойчивому идентификатору фигуры,
5	// который приходит с сервера, — это то, что превращает перерисовку в анимацию:
6	// и ход, и посадку десанта видно как движение, а не как мигание.
7	import { spriteSvg, PIECE_LETTER, PIECE_NAME } from './sprites.js';
8	
9	const FILES = 'abcdefgh';
10	
11	export function squareName(file, rank) {
12	  return `${FILES[file]}${rank}`;
13	}
14	
15	export class BoardView {
16	  constructor({ squaresEl, piecesEl, boardEl, onSelect }) {
17	    this.squaresEl = squaresEl;
18	    this.piecesEl = piecesEl;
19	    this.boardEl = boardEl;
20	    this.onSelect = onSelect;
21	
22	    this.squares = new Map(); // имя поля -> элемент
23	    this.pieceEls = new Map(); // идентификатор фигуры -> элемент
24	    this.selected = null;
25	    this.legalMoves = {};
26	    this.board = [];
27	    this.pieceSet = 'xeno';
28	    this.badges = true;
29	    this.locked = false;
30	
31	    this.#buildSquares();
32	    this.#bindPointer();
33	  }
34	
35	  #buildSquares() {
36	    const frag = document.createDocumentFragment();
37	    for (let r = 8; r >= 1; r--) {
38	      for (let f = 0; f < 8; f++) {
39	        const name = squareName(f, r);
40	        const el = document.createElement('div');
41	        el.className = `sq ${(f + r) % 2 === 0 ? 'dark' : 'light'}`;
42	        el.dataset.square = name;
43	        if (f === 0 || r === 1) {
44	          const c = document.createElement('span');
45	          c.className = 'coord';
46	          c.textContent = f === 0 && r === 1 ? name : f === 0 ? String(r) : FILES[f];
47	          el.appendChild(c);
48	        }
49	        this.squares.set(name, el);
50	        frag.appendChild(el);
51	      }
52	    }
53	    this.squaresEl.appendChild(frag);
54	  }
55	
56	  // ─────────────────────────────────────────── ввод
57	
58	  #squareFromPoint(x, y) {
59	    const rect = this.boardEl.getBoundingClientRect();
60	    const f = Math.floor(((x - rect.left) / rect.width) * 8);
61	    const r = 8 - Math.floor(((y - rect.top) / rect.height) * 8);
62	    if (f < 0 || f > 7 || r < 1 || r > 8) return null;
63	    return squareName(f, r);
64	  }
65	
66	  /**
67	   * Указатель, а не нативный drag&drop: последний тащит призрачную картинку,
68	   * не работает на касании и не даёт управлять анимацией. Плюс поддержан
69	   * режим «клик по источнику — клик по цели», которым играет большинство.
70	   */
71	  #bindPointer() {
72	    let dragging = null;
73	
74	    this.boardEl.addEventListener('pointerdown', (ev) => {
75	      if (this.locked) return;
76	      const sq = this.#squareFromPoint(ev.clientX, ev.clientY);
77	      if (!sq) return;
78	
79	      // Второй клик по подсвеченной цели завершает ход.
80	      if (this.selected && this.legalMoves[this.selected]?.includes(sq)) {
81	        this.onSelect({ from: this.selected, to: sq });
82	        this.clearSelection();
83	        return;
84	      }
85	
86	      const piece = this.board.find((p) => p.square === sq);
87	      if (!piece || !this.legalMoves[sq]) {
88	        this.clearSelection();
89	        return;
90	      }
91	
92	      this.select(sq);
93	      const el = this.pieceEls.get(piece.id);
94	      if (!el) return;
95	      dragging = { from: sq, el, pointerId: ev.pointerId, moved: false };
96	      el.classList.add('dragging');
97	      this.boardEl.setPointerCapture(ev.pointerId);
98	      ev.preventDefault();
99	    });
100	
101	    this.boardEl.addEventListener('pointermove', (ev) => {
102	      if (!dragging) return;
103	      const rect = this.boardEl.getBoundingClientRect();
104	      const size = rect.width / 8;
105	      const x = ev.clientX - rect.left - size / 2;
106	      const y = ev.clientY - rect.top - size / 2;
107	      dragging.moved = true;
108	      dragging.el.style.transform = `translate(${x}px, ${y}px)`;
109	    });
110	
111	    const finish = (ev) => {
112	      if (!dragging) return;
113	      const { from, el, moved } = dragging;
114	      dragging = null;
115	      el.classList.remove('dragging');
116	      el.style.transform = '';
117	      this.#placePiece(el, from); // вернём на место; сервер подтвердит настоящий ход
118	      try {
119	        this.boardEl.releasePointerCapture(ev.pointerId);
120	      } catch {
121	        /* захват мог уже отпуститься сам */
122	      }
123	      if (!moved) return; // это был обычный клик — выбор уже сделан
124	      const to = this.#squareFromPoint(ev.clientX, ev.clientY);
125	      if (!to || to === from) return;
126	      if (!this.legalMoves[from]?.includes(to)) return;
127	      this.onSelect({ from, to });
128	      this.clearSelection();
129	    };
130	
131	    this.boardEl.addEventListener('pointerup', finish);
132	    this.boardEl.addEventListener('pointercancel', finish);
133	  }
134	
135	  select(sq) {
136	    this.clearSelection();
137	    this.selected = sq;
138	    this.squares.get(sq)?.classList.add('sel');
139	    for (const to of this.legalMoves[sq] || []) {
140	      const el = this.squares.get(to);
141	      if (!el) continue;
142	      el.classList.add('target');
143	      if (this.board.some((p) => p.square === to)) el.classList.add('capture');
144	    }
145	  }
146	
147	  clearSelection() {
148	    if (this.selected) this.squares.get(this.selected)?.classList.remove('sel');
149	    this.selected = null;
150	    for (const el of this.squares.values()) el.classList.remove('target', 'capture');
151	  }
152	
153	  // ─────────────────────────────────────────── отрисовка
154	
155	  #placePiece(el, square) {
156	    const f = FILES.indexOf(square[0]);
157	    const r = Number(square[1]);
158	    const tx = `${f * 100}%`;
159	    const ty = `${(8 - r) * 100}%`;
160	    el.style.setProperty('--tx', tx);
161	    el.style.setProperty('--ty', ty);
162	    el.style.transform = `translate(${tx}, ${ty})`;
163	  }
164	
165	  #createPiece(p) {
166	    const el = document.createElement('div');
167	    el.className = 'piece';
168	    el.dataset.id = p.id;
169	    el.dataset.color = p.color;
170	    el.title = `${p.color === 'w' ? 'морпехи' : 'ксено'}: ${PIECE_NAME[p.type]}`;
171	    el.innerHTML = spriteSvg(this.pieceSet, p.color, p.type);
172	    if (this.badges) {
173	      const b = document.createElement('span');
174	      b.className = 'badge';
175	      b.textContent = PIECE_LETTER[p.type];
176	      el.appendChild(b);
177	    }
178	    return el;
179	  }
180	
181	  /**
182	   * @param {Array} board       фигуры со стабильными идентификаторами
183	   * @param {Set}   landedIds   кто именно только что высадился — им играем посадку
184	   */
185	  render(board, { legalMoves = {}, lastMove = null, checkSquare = null, reinforced = [], landedIds = null } = {}) {
186	    this.board = board;
187	    this.legalMoves = legalMoves;
188	
189	    const seen = new Set();
190	    for (const p of board) {
191	      seen.add(p.id);
192	      let el = this.pieceEls.get(p.id);
193	      if (!el) {
194	        el = this.#createPiece(p);
195	        this.pieceEls.set(p.id, el);
196	        this.piecesEl.appendChild(el);
197	        this.#placePiece(el, p.square);
198	        if (landedIds && landedIds.has(p.id)) {
199	          // Порядок важен: сначала позиция, потом класс анимации, иначе
200	          // переменные --tx/--ty ещё не заданы и фигура прилетает в угол.
201	          el.classList.add('landing');
202	          el.addEventListener('animationend', () => el.classList.remove('landing'), { once: true });
203	        }
204	      } else {
205	        const type = el.dataset.type;
206	        if (type && type !== p.type) el.innerHTML = spriteSvg(this.pieceSet, p.color, p.type);
207	        this.#placePiece(el, p.square);
208	      }
209	      el.dataset.type = p.type;
210	      el.dataset.square = p.square;
211	    }
212	
213	    for (const [id, el] of this.pieceEls) {
214	      if (seen.has(id)) continue;
215	      el.remove();
216	      this.pieceEls.delete(id);
217	    }
218	
219	    for (const el of this.squares.values()) el.classList.remove('last', 'check', 'reinforced');
220	    if (lastMove) {
221	      this.squares.get(lastMove.from)?.classList.add('last');
222	      this.squares.get(lastMove.to)?.classList.add('last');
223	    }
224	    if (checkSquare) this.squares.get(checkSquare)?.classList.add('check');
225	    for (const sq of reinforced) this.squares.get(sq)?.classList.add('reinforced');
226	  }
227	
228	  /** Ударная волна на полях высадки. */
229	  shockwave(squares) {
230	    for (const sq of squares) {
231	      const el = this.squares.get(sq);
232	      if (!el) continue;
233	      const wave = document.createElement('span');
234	      wave.className = 'shock';
235	      el.appendChild(wave);
236	      setTimeout(() => wave.remove(), 500);
237	    }
238	  }
239	
240	  setLocked(locked) {
241	    this.locked = locked;
242	    this.boardEl.classList.toggle('busy', locked);
243	    if (locked) this.clearSelection();
244	  }
245	
246	  setPieceSet(name, badges) {
247	    if (name === this.pieceSet && badges === this.badges) return;
248	    this.pieceSet = name;
249	    this.badges = badges;
250	    // Набор сменился целиком — проще пересоздать слой, чем чинить каждую фигуру.
251	    for (const el of this.pieceEls.values()) el.remove();
252	    this.pieceEls.clear();
253	  }
254	}
