1	// Склейка: поток событий, отрисовка, ввод.
2	//
3	// Клиент намеренно ничего не решает сам: легальность ходов, расписание десанта
4	// и счёт жетонов живут на сервере и приходят готовыми. Здесь только три вещи —
5	// отрисовка, ввод указателя и тайминги анимаций.
6	import { BoardView } from './board.js';
7	import { PIECE_LETTER } from './sprites.js';
8	
9	const $ = (id) => document.getElementById(id);
10	
11	const el = {
12	  turn: $('turn-line'),
13	  hold: $('hold-line'),
14	  auto: $('auto-line'),
15	  linkDot: $('link-dot'),
16	  linkText: $('link-text'),
17	  evalbar: $('evalbar'),
18	  evalFill: $('eval-fill'),
19	  evalLabel: $('eval-label'),
20	  moves: $('moves'),
21	  drops: $('drops'),
22	  banner: $('drop-banner'),
23	  bannerPhase: $('drop-phase'),
24	  bannerBar: $('drop-bar'),
25	  pipsW: $('pips-w'),
26	  pipsB: $('pips-b'),
27	  rollW: $('roll-w'),
28	  rollB: $('roll-b'),
29	  die1: $('die1'),
30	  die2: $('die2'),
31	  diceText: $('dice-text'),
32	  overlay: $('overlay'),
33	  overTitle: $('over-title'),
34	  overSub: $('over-sub'),
35	  promo: $('promo'),
36	  drawer: $('drawer'),
37	  toast: $('toast'),
38	};
39	
40	let state = null;
41	let pendingPromotion = null;
42	let landedIds = new Set();
43	let reinforcedSquares = [];
44	
45	const board = new BoardView({
46	  squaresEl: $('squares'),
47	  piecesEl: $('pieces'),
48	  boardEl: $('board'),
49	  onSelect: onMoveAttempt,
50	});
51	
52	// ─────────────────────────────────────────── сеть
53	
54	async function post(path, body) {
55	  const res = await fetch(path, {
56	    method: 'POST',
57	    headers: { 'Content-Type': 'application/json' },
58	    body: JSON.stringify(body || {}),
59	  });
60	  const data = await res.json().catch(() => ({ ok: false, message: 'НЕЧИТАЕМЫЙ ОТВЕТ' }));
61	  if (!data.ok) {
62	    // Устаревшая версия — не ошибка игрока: просто перечитываем состояние.
63	    if (data.code === 'STALE_VERSION') {
64	      await refresh();
65	      return data;
66	    }
67	    toast(data.message || 'ОТКАЗАНО');
68	  }
69	  return data;
70	}
71	
72	async function refresh() {
73	  const res = await fetch('/api/state');
74	  applyState(await res.json());
75	}
76	
77	function connect() {
78	  const es = new EventSource('/api/events');
79	
80	  es.onopen = () => setLink(true);
81	  es.onerror = () => setLink(false);
82	
83	  const stateEvents = ['snapshot', 'move', 'settings', 'state'];
84	  for (const name of stateEvents) {
85	    es.addEventListener(name, (e) => applyState(JSON.parse(e.data)));
86	  }
87	
88	  es.addEventListener('eval', (e) => renderEval(JSON.parse(e.data)));
89	
90	  es.addEventListener('thinking', (e) => {
91	    const t = JSON.parse(e.data);
92	    el.turn.classList.add('thinking');
93	    el.turn.textContent = (t.side === 'w' ? 'МОРПЕХИ' : 'КСЕНО') + ' ДУМАЮТ · ' + t.level;
94	  });
95	
96	  es.addEventListener('dice', (e) => {
97	    const { roll, text } = JSON.parse(e.data);
98	    animateDice(roll, text);
99	  });
100	
101	  es.addEventListener('drop:start', (e) => {
102	    applyState(JSON.parse(e.data));
103	    showBanner(true);
104	  });
105	
106	  es.addEventListener('drop:progress', (e) => renderProgress(JSON.parse(e.data)));
107	
108	  es.addEventListener('drop:done', (e) => {
109	    const { drop, state: next } = JSON.parse(e.data);
110	    const squares = [...drop.white, ...drop.black].map((p) => p.square);
111	    const before = new Set((state?.board || []).map((p) => p.id));
112	    landedIds = new Set(next.board.filter((p) => !before.has(p.id)).map((p) => p.id));
113	    reinforcedSquares = squares;
114	    showBanner(false);
115	    applyState(next);
116	    board.shockwave(squares);
117	    toast(dropHeadline(drop));
118	  });
119	
120	  es.addEventListener('drop:skipped', (e) => {
121	    const data = JSON.parse(e.data);
122	    showBanner(false);
123	    if (data.state) applyState(data.state);
124	    toast(`ДЕСАНТ ОТЛОЖЕН: ${String(data.reason || '').toUpperCase()}`);
125	  });
126	
127	  return es;
128	}
129	
130	function setLink(ok) {
131	  el.linkDot.classList.toggle('off', !ok);
132	  el.linkText.textContent = ok ? 'СВЯЗЬ' : 'НЕТ СВЯЗИ';
133	}
134	
135	// ─────────────────────────────────────────── отрисовка состояния
136	
137	function applyState(next) {
138	  if (!next || typeof next.version !== 'number') return;
139	  const prev = state;
140	  state = next;
141	
142	  if (prev && prev.sessionId && next.sessionId && prev.sessionId !== next.sessionId) {
143	    toast('СЕРВЕР ПЕРЕЗАПУЩЕН');
144	  }
145	
146	  board.setPieceSet(next.settings.pieceSet || 'xeno', next.settings.pieceBadges !== false);
147	
148	  const last = next.moveLog[next.moveLog.length - 1] || null;
149	  const kingSquare = next.inCheck
150	    ? next.board.find((p) => p.type === 'k' && p.color === next.turn)?.square
151	    : null;
152	
153	  board.render(next.board, {
154	    legalMoves: next.phase === 'dropping' ? {} : next.legalMoves,
155	    lastMove: last ? { from: last.from, to: last.to } : null,
156	    checkSquare: kingSquare,
157	    reinforced: reinforcedSquares,
158	    landedIds,
159	  });
160	  landedIds = new Set();
161	  if (last) reinforcedSquares = [];
162	
163	  board.setLocked(next.phase === 'dropping' || Boolean(next.gameOver));
164	
165	  renderHeader(next);
166	  renderMoves(next);
167	  renderDrops(next);
168	  renderControls(next);
169	  renderGameOver(next);
170	  if (!next.settings.showEval) {
171	    el.evalbar.classList.add('hidden');
172	    el.evalLabel.textContent = '——';
173	  } else {
174	    el.evalbar.classList.remove('hidden');
175	  }
176	}
177	
178	function renderHeader(s) {
179	  el.turn.classList.remove('thinking');
180	  const seats = s.settings.players || { w: 'human', b: 'human' };
181	  const who = (c) => (seats[c] === 'computer' ? 'ИИ' : 'ЧЕЛ');
182	  const side = s.turn === 'w' ? 'МОРПЕХИ' : 'КСЕНО';
183	  const moveNo = Math.floor(s.moveLog.length / 2) + 1;
184	  el.turn.textContent = s.gameOver ? 'ПАРТИЯ ОКОНЧЕНА' : `ХОД ${moveNo} · ХОДЯТ ${side}${s.inCheck ? ' · ШАХ' : ''}`;
185	  el.hold.textContent = `М:${who('w')} К:${who('b')} · ТРЮМ ${s.pieceCount}/32 · СВОБОДНО ${s.freeSlots} · ${s.storyteller.name}`;
186	
187	  if (s.freeSlots < 2) {
188	    el.auto.textContent = 'ТРЮМ ПОЛОН — ДЕСАНТ ПОСЛЕ ПЕРВЫХ ПОТЕРЬ';
189	  } else if (s.movesUntilAutoDrop === null) {
190	    el.auto.textContent = 'АВТО-ДЕСАНТ ВЫКЛЮЧЕН';
191	  } else {
192	    el.auto.textContent = `АВТО-ДЕСАНТ ЧЕРЕЗ ${s.movesUntilAutoDrop} ХОД(ОВ)`;
193	  }
194	}
195	
196	function renderMoves(s) {
197	  const rows = [];
198	  const dropAfter = new Map();
199	  for (const d of s.dropLog) dropAfter.set(d.afterPly, d);
200	
201	  for (let i = 0; i < s.moveLog.length; i += 2) {
202	    const w = s.moveLog[i];
203	    const b = s.moveLog[i + 1];
204	    rows.push(
205	      `<div class="row"><span class="n">${w.n}.</span><span>${w.san}</span><span>${b ? b.san : ''}</span></div>`,
206	    );
207	    for (const ply of [i + 1, i + 2]) {
208	      const d = dropAfter.get(ply);
209	      if (d) rows.push(`<div class="row"><span class="sep">═══ ДЕСАНТ #${d.id} ═══</span></div>`);
210	    }
211	  }
212	  const zero = dropAfter.get(0);
213	  if (zero) rows.unshift(`<div class="row"><span class="sep">═══ ДЕСАНТ #${zero.id} ═══</span></div>`);
214	  el.moves.innerHTML = rows.join('') || '<span style="color:var(--phosphor-faint)">Ходов пока нет.</span>';
215	  el.moves.scrollTop = el.moves.scrollHeight;
216	}
217	
218	function pieceList(list) {
219	  return list.map((p) => `${PIECE_LETTER[p.type]}${p.square}`).join(' ') || '—';
220	}
221	
222	function dropHeadline(d) {
223	  const abs = Math.abs(d.delta);
224	  return abs <= 15 ? `ДЕСАНТ #${d.id}: БАЛАНС СОХРАНЁН (Δ ${d.delta} СП)` : `ДЕСАНТ #${d.id}: Δ ${d.delta} СП`;
225	}
226	
227	function renderDrops(s) {
228	  if (s.dropLog.length === 0) {
229	    el.drops.innerHTML = '<div style="color:var(--phosphor-faint)">Высадок ещё не было.</div>';
230	    return;
231	  }
232	  const html = [...s.dropLog]
233	    .reverse()
234	    .map((d) => {
235	      const trigger = d.trigger === 'dice' ? `БРОСОК ${d.dice.d1}+${d.dice.d2}` : 'АВТОМАТИЧЕСКИ';
236	      const balanced = Math.abs(d.delta) <= 15 ? '<span class="chip">БАЛАНС СОХРАНЁН</span>' : '';
237	      const widened = d.toleranceWidened
